PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, role TEXT NOT NULL, name TEXT NOT NULL, login TEXT NOT NULL UNIQUE, hash TEXT NOT NULL, createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id TEXT PRIMARY KEY, teacherId TEXT NOT NULL REFERENCES users, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members(classId TEXT REFERENCES classes ON DELETE CASCADE, userId TEXT REFERENCES users ON DELETE CASCADE, PRIMARY KEY(classId,userId));
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY,classId TEXT NOT NULL REFERENCES classes ON DELETE CASCADE,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS team_members(teamId TEXT REFERENCES teams ON DELETE CASCADE,userId TEXT REFERENCES users ON DELETE CASCADE,PRIMARY KEY(teamId,userId));
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY,classId TEXT NOT NULL REFERENCES classes ON DELETE CASCADE,title TEXT NOT NULL,settings TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,classId TEXT NOT NULL REFERENCES classes ON DELETE CASCADE,ownerId TEXT NOT NULL REFERENCES users,teamId TEXT REFERENCES teams ON DELETE CASCADE,assignmentId TEXT REFERENCES assignments ON DELETE SET NULL,title TEXT NOT NULL,draft TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,origin TEXT,createdAt TEXT NOT NULL,updatedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,authorId TEXT NOT NULL REFERENCES users,kind TEXT NOT NULL,source TEXT NOT NULL,body TEXT NOT NULL,personal INTEGER NOT NULL DEFAULT 0,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,authorId TEXT NOT NULL REFERENCES users,kind TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,bytes BLOB NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,n INTEGER NOT NULL,authorId TEXT NOT NULL REFERENCES users,snapshot TEXT NOT NULL,reason TEXT NOT NULL,restoredFrom TEXT,createdAt TEXT NOT NULL,UNIQUE(projectId,n));
CREATE TABLE IF NOT EXISTS exhibits(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,versionId TEXT NOT NULL REFERENCES versions ON DELETE CASCADE,authorId TEXT NOT NULL REFERENCES users,title TEXT NOT NULL,description TEXT NOT NULL,stage TEXT NOT NULL,displayName TEXT NOT NULL,assets TEXT NOT NULL,remix INTEGER NOT NULL,status TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,versionId TEXT NOT NULL REFERENCES versions ON DELETE CASCADE,authorId TEXT NOT NULL REFERENCES users,exhibitId TEXT REFERENCES exhibits ON DELETE CASCADE,recordId TEXT REFERENCES records ON DELETE CASCADE,body TEXT NOT NULL,kind TEXT NOT NULL,published INTEGER NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS responses(id TEXT PRIMARY KEY,feedbackId TEXT NOT NULL REFERENCES feedback ON DELETE CASCADE,authorId TEXT NOT NULL REFERENCES users,status TEXT NOT NULL,reason TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,teacherId TEXT NOT NULL REFERENCES users,versionId TEXT REFERENCES versions ON DELETE CASCADE,recordId TEXT REFERENCES records ON DELETE CASCADE,axis TEXT NOT NULL,note TEXT NOT NULL,nextQuestion TEXT NOT NULL,state TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_claims(id TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users ON DELETE CASCADE,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,tool TEXT NOT NULL,jobId TEXT UNIQUE,status TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS project_class ON projects(classId,updatedAt);
CREATE INDEX IF NOT EXISTS record_project ON records(projectId);
CREATE INDEX IF NOT EXISTS version_project ON versions(projectId);
CREATE INDEX IF NOT EXISTS exhibit_status ON exhibits(status);
CREATE INDEX IF NOT EXISTS asset_project ON assets(projectId);
CREATE INDEX IF NOT EXISTS feedback_project ON feedback(projectId);
CREATE TABLE IF NOT EXISTS school_config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS asset_keys(projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,authorId TEXT NOT NULL REFERENCES users,clientKey TEXT NOT NULL,fingerprint TEXT NOT NULL,assetId TEXT NOT NULL REFERENCES assets ON DELETE CASCADE,PRIMARY KEY(projectId,authorId,clientKey));

CREATE TABLE IF NOT EXISTS observation_drafts(id TEXT PRIMARY KEY,projectId TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,teacherId TEXT NOT NULL REFERENCES users,versionId TEXT REFERENCES versions ON DELETE CASCADE,recordId TEXT REFERENCES records ON DELETE CASCADE,axis TEXT NOT NULL,note TEXT NOT NULL,quote TEXT NOT NULL,nextQuestion TEXT NOT NULL,model TEXT NOT NULL,promptVersion TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS observation_sources(observationId TEXT PRIMARY KEY REFERENCES observations ON DELETE CASCADE,draftId TEXT NOT NULL REFERENCES observation_drafts ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS observation_support(observationId TEXT PRIMARY KEY REFERENCES observations ON DELETE CASCADE);
